package com.doulala.android;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;
import com.doulala.android.video.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.channels.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;
/** Foreground-only sequential video client. A configured user gateway is required. */
public final class SequentialVideoActivity extends Activity {
 private static final int PICK_JOB=801, SAVE_RESULT=802, MAX_JOB=512*1024; private static final Set<String> ACTIVE=ConcurrentHashMap.newKeySet();
 private final ExecutorService worker=Executors.newSingleThreadExecutor(); private volatile boolean cancelled; private String spaceId,jobText; private Job job; private LinearLayout body; private TextView status; private String completedOutput;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.setup(this);spaceId=getIntent().getStringExtra("spaceId");if(spaceId==null||!spaceId.matches("Space([0-9]|[1-5][0-9]|6[0-3])")) { finish(); return; }render();}
 private void render(){ScrollView scroll=new ScrollView(this);body=Ui.column(this);body.setPadding(Ui.dp(this,14),Ui.dp(this,8),Ui.dp(this,14),Ui.dp(this,24));scroll.addView(body);setContentView(scroll);LinearLayout h=Ui.row(this);h.addView(Ui.button(this,"‹ 返回",v->finish()));h.addView(Ui.title(this,"连续视频",22),new LinearLayout.LayoutParams(0,-2,1));body.addView(h);body.addView(Ui.text(this,"仅在此屏幕前台顺序运行。需要你自己的 HTTPS 网关适配器；不会读取账号、Cookie 或自动操作平台。",13,Ui.MUTED));body.addView(Ui.button(this,"导入任务 JSON",v->pick())); if(completedOutput!=null) body.addView(Ui.button(this,"导出最后完成的视频",v->exportResult()));if(job==null){body.addView(Ui.text(this,"尚未导入任务。网关端点没有默认值，也不声明兼容任何 Dola 服务。",14,Ui.MUTED));return;}LinearLayout card=Ui.card(this);card.addView(Ui.title(this,"任务 "+job.id+" · "+job.segments.size()+" 段",17));card.addView(Ui.text(this,"网关："+job.gateway+"\n提交前会显示此源和段数；token 只保存在当前内存。",13,Ui.MUTED));for(VideoProvider.Segment s:job.segments)card.addView(Ui.text(this,(s.index()+1)+". "+s.model()+"\n"+s.prompt()+"\n原始参考："+s.originalRefs().size(),13,Ui.INK));body.addView(card);LinearLayout form=Ui.card(this);EditText token=Ui.edit(this,"网关 API token（仅内存）","");token.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);token.setSaveEnabled(false);form.addView(token);form.addView(Ui.button(this,"确认并顺序运行",v->{String t=token.getText().toString();token.setText("");confirm(t);}));form.addView(Ui.button(this,"取消当前运行",v->{cancelled=true;status.setText("取消已请求；不会提交下一段。");}));status=Ui.text(this,"待确认。",14,Ui.MUTED);form.addView(status);body.addView(form);}
 private void pick(){if(ACTIVE.contains(spaceId)){Ui.toast(this,"运行中不能导入或替换任务");return;}Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json");startActivityForResult(i,PICK_JOB);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null||d.getData()==null)return; if(r==SAVE_RESULT){if("content".equalsIgnoreCase(d.getData().getScheme()))copyResult(d.getData());return;} if(r!=PICK_JOB)return;Uri u=d.getData();if(!"content".equalsIgnoreCase(u.getScheme())){Ui.toast(this,"仅接受系统文档选择器文件");return;}worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(u)){if(in==null)throw new IOException("无法读取");byte[] bytes=readBounded(in,MAX_JOB);Job parsed=Job.parse(new String(bytes,StandardCharsets.UTF_8));runOnUiThread(()->{job=parsed;jobText=null;render();});}catch(Exception e){message("任务导入失败："+safe(e));}});}
 private void confirm(String token){new AlertDialog.Builder(this).setTitle("确认提交到网关？").setMessage("将向\n"+job.gateway+"\n顺序提交 "+job.segments.size()+" 段。该服务由你配置，非内置平台接口。Token 不保存。") .setNegativeButton("取消",null).setPositiveButton("开始",(d,w)->run(token)).show();}
 private void run(String token){final Job runJob=job; if(runJob==null)return; if(!ACTIVE.add(spaceId)){status.setText("此空间已有运行器；请勿重复启动。");return;}cancelled=false;status.setText("正在运行第一个可恢复段…");worker.execute(()->{FileChannel channel=null;FileLock lock=null;SpaceReset.BrowserGate profileGate=null;try{profileGate=SpaceReset.acquireBrowserGate(this,Integer.parseInt(spaceId.substring(5)));Path base=getFilesDir().toPath().resolve("video-"+spaceId);Files.createDirectories(base);channel=FileChannel.open(base.resolve("runner.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);lock=channel.tryLock();if(lock==null)throw new IOException("此空间已有其他运行器");VideoGateway gateway=new VideoGateway(runJob.gateway,token,()->cancelled||isDestroyed());LastFrameExtractor extractor=createExtractor();SequentialVideoOrchestrator o=new SequentialVideoOrchestrator(gateway,extractor,new VideoJobStore(this,spaceId,runJob.gateway));SequenceCheckpointStore.Snapshot done=o.run(runJob.id,runJob.segments,new SequentialVideoOrchestrator.Options(2400,base.resolve(VideoJobStore.digest(runJob.gateway)).resolve(runJob.id),()->cancelled||isDestroyed())); if(!cancelled){SequenceCheckpointStore.Entry last=done.entries().get(runJob.segments.size()-1);completedOutput=last==null?null:last.outputPath(); runOnUiThread(()->render());} message(cancelled?"已取消；检查点已保留。":"全部段已完成；可通过导出按钮取用结果。");}catch(Exception e){message("视频任务失败（未伪造成功）："+safe(e));}finally{try{if(lock!=null)lock.release();if(channel!=null)channel.close();if(profileGate!=null)profileGate.close();}catch(Exception ignored){}ACTIVE.remove(spaceId);}});}
 private LastFrameExtractor createExtractor() { return (video,jpg) -> { java.io.File v=video.toFile(), out=jpg.toFile(); FfmpegLastFrame.extract(this,v,out,()->cancelled||Thread.currentThread().isInterrupted()); if(!out.isFile() || out.length()==0) throw new IOException("帧提取未产生 JPEG"); }; }
 private void exportResult(){if(completedOutput==null)return;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("video/mp4").putExtra(Intent.EXTRA_TITLE,"sequence-"+job.id+".mp4");startActivityForResult(i,SAVE_RESULT);} private void copyResult(Uri uri){final String source=completedOutput;worker.execute(()->{try(InputStream in=Files.newInputStream(Paths.get(source));OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法打开目标");byte[] b=new byte[8192];for(int n;(n=in.read(b))>=0;)out.write(b,0,n);message("视频已导出");}catch(Exception e){message("导出失败："+safe(e));}});} @Override protected void onStop(){if(spaceId!=null&&ACTIVE.contains(spaceId))cancelled=true;super.onStop();} @Override protected void onDestroy(){cancelled=true;worker.shutdownNow();super.onDestroy();}
 private void message(String s){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&status!=null)status.setText(s);});}private static String safe(Exception e){String s=e.getMessage();return s==null?e.getClass().getSimpleName():s.replaceAll("(?i)bearer\\s+[^ ]+","Bearer [redacted]");}
 private static String jsonValue(Object value){String container=new JSONArray().put(value).toString();return container.substring(1,container.length()-1);}
 private static byte[] readBounded(InputStream in,int max)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];for(int n;(n=in.read(b))>=0;){if(o.size()+n>max)throw new IOException("文件过大");o.write(b,0,n);}return o.toByteArray();}
 static final class Job {final String id,gateway;final List<VideoProvider.Segment> segments;Job(String i,String g,List<VideoProvider.Segment>s){id=i;gateway=g;segments=s;}static Job parse(String raw)throws Exception{JSONObject r=new JSONObject(raw);if(r.optInt("schemaVersion",0)!=1)throw new IOException("仅支持 schemaVersion=1");String id=r.getString("sequenceId");if(!id.matches("[A-Za-z0-9_-]{1,80}"))throw new IOException("sequenceId 无效");String gateway=r.getString("gateway");new VideoGateway(gateway,"");JSONArray a=r.getJSONArray("segments");if(a.length()<1||a.length()>100)throw new IOException("segments 必须为 1..100");ArrayList<VideoProvider.Segment> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);String model=x.getString("model"),prompt=x.getString("prompt");if(model.trim().isEmpty()||prompt.length()>20000)throw new IOException("段模型或提示词无效");JSONArray refs=x.optJSONArray("referenceImages");ArrayList<String> rs=new ArrayList<>();if(refs!=null)for(int q=0;q<refs.length();q++){String u=refs.getString(q);if(!u.startsWith("https://"))throw new IOException("参考必须为 HTTPS URL");rs.add(u);}JSONObject ps=x.optJSONObject("params");Map<String,String> pm=new TreeMap<>();if(ps!=null)for(Iterator<String>it=ps.keys();it.hasNext();){String k=it.next();Object v=ps.get(k);if(k.length()>100||String.valueOf(v).length()>2000)throw new IOException("params 过大");pm.put(k,jsonValue(v));}out.add(new VideoProvider.Segment(i,model,prompt,rs,pm));}return new Job(id,gateway,Collections.unmodifiableList(new ArrayList<>(out)));}}
}








